This appears to be caused by a race between the processing of the "StartGame" immediate order and another client's non-immediate orders.

Repro case to force the issue:
```diff
diff --git a/OpenRA.Game/Network/UnitOrders.cs b/OpenRA.Game/Network/UnitOrders.cs
index 6345721f43..c1abd554c2 100644
--- a/OpenRA.Game/Network/UnitOrders.cs
+++ b/OpenRA.Game/Network/UnitOrders.cs
@@ -9,6 +9,7 @@
  */
 #endregion
 
+using System;
 using System.Collections.Generic;
 using System.Linq;
 using OpenRA.Server;
@@ -135,7 +136,12 @@ internal static void ProcessOrder(OrderManager orderManager, World world, int cl
                                                else
                                                        Game.AddSystemLine("The game has started.");
 
-                                               Game.StartGame(orderManager.LobbyInfo.GlobalSettings.Map, WorldType.Regular);
+                                               Action foo = () => Game.StartGame(orderManager.LobbyInfo.GlobalSettings.Map, WorldType.Regular);
+
+                                               if (orderManager.LocalClient.IsAdmin)
+                                                       foo();
+                                               else
+                                                       Game.RunAfterDelay(200, foo);
                                                break;
                                        }
```

